-- Block 1: Catalog (HISTORICO service type + vehicle size)
-- ═══════════════════════════════════════════════════

INSERT INTO service_types (tenant_id, code, name, active)
VALUES (1, 'HISTORICO', 'Historico', true)
ON CONFLICT (tenant_id, code) DO NOTHING;

INSERT INTO vehicle_sizes (tenant_id, code, name, sort_order, active)
VALUES (1, 'HISTORICO', 'Historico', 99, true)
ON CONFLICT (tenant_id, code) DO NOTHING;

INSERT INTO service_prices (tenant_id, service_type_id, vehicle_size_id, amount, currency, effective_from)
SELECT 1, st.id, vs.id, 1.00, 'MXN', '2026-01-01'
FROM service_types st
JOIN vehicle_sizes vs ON vs.code = 'HISTORICO' AND vs.tenant_id = 1
WHERE st.code = 'HISTORICO' AND st.tenant_id = 1
ON CONFLICT (tenant_id, service_type_id, vehicle_size_id, currency, effective_from) DO NOTHING;

