JOIN business_days bd ON t.business_day_id = bd.id
JOIN employees e ON e.full_name = 'GUADALUPE' AND e.tenant_id = 1
WHERE bd.business_date = '2026-01-01' AND t.daily_seq = 42 AND bd.tenant_id = 1
ON CONFLICT (tenant_id, ticket_id, employee_id) DO NOTHING;

