INSERT INTO expenses (tenant_id, business_day_id, expense_date, category, amount, description)
SELECT 1, bd.id, '2026-02-13', 'OTHER', 8965.00, 'Gastos del dia (Excel import)'
FROM business_days bd
WHERE bd.business_date = '2026-02-13' AND bd.tenant_id = 1
  AND NOT EXISTS (
    SELECT 1 FROM expenses e
    WHERE e.business_day_id = bd.id AND e.tenant_id = 1 AND e.description = 'Gastos del dia (Excel import)'
  );

