INSERT INTO expenses (tenant_id, business_day_id, expense_date, category, amount, description)
SELECT 1, bd.id, '2026-02-28', 'OTHER', 5772.00, 'Gastos del dia (Excel import)'
FROM business_days bd
WHERE bd.business_date = '2026-02-28' AND bd.tenant_id = 1
