INSERT INTO business_days (tenant_id, business_date, status)
VALUES (1, '2026-03-09', 'CLOSED')
ON CONFLICT (tenant_id, business_date) DO NOTHING;

INSERT INTO shifts (tenant_id, business_day_id, shift_type, status)
SELECT 1, id, 'MATUTINO', 'CLOSED' FROM business_days
WHERE business_date = '2026-03-09' AND tenant_id = 1
ON CONFLICT (tenant_id, business_day_id, shift_type) DO NOTHING;

INSERT INTO shifts (tenant_id, business_day_id, shift_type, status)
SELECT 1, id, 'VESPERTINO', 'CLOSED' FROM business_days
WHERE business_date = '2026-03-09' AND tenant_id = 1
ON CONFLICT (tenant_id, business_day_id, shift_type) DO NOTHING;

INSERT INTO tickets (
  tenant_id, business_day_id, shift_id, service_type_id, vehicle_size_id,
  daily_seq, nota_number, vehicle_description,
  price_amount, currency, payment_method, courtesy, courtesy_reason, status
)
SELECT
  1, bd.id, s.id, st.id, vs.id,
  1, '137234', 'SILVERADO AZUL',
  93.00, 'MXN', 'CASH', false, NULL, 'ACTIVE'
FROM business_days bd
JOIN shifts s ON s.business_day_id = bd.id AND s.shift_type = 'MATUTINO'
