INSERT INTO tickets (
  tenant_id, business_day_id, shift_id, service_type_id, vehicle_size_id,
  daily_seq, nota_number, vehicle_description,
  price_amount, currency, payment_method, courtesy, courtesy_reason, status
)
SELECT
  1, bd.id, s.id, st.id, vs.id,
  2, '140314', 'MERCEDES NEGRO',
  108.00, 'MXN', 'CASH', false, NULL, 'ACTIVE'
FROM business_days bd
JOIN shifts s ON s.business_day_id = bd.id AND s.shift_type = 'VESPERTINO'
JOIN service_types st ON st.code = 'HISTORICO' AND st.tenant_id = 1
JOIN vehicle_sizes vs ON vs.code = 'HISTORICO' AND vs.tenant_id = 1
WHERE bd.business_date = '2026-04-21' AND bd.tenant_id = 1
ON CONFLICT (tenant_id, business_day_id, daily_seq) DO NOTHING;

