INSERT INTO ticket_assignments (tenant_id, ticket_id, employee_id, share_pct)
SELECT 1, t.id, e.id, 100
FROM tickets t
JOIN business_days bd ON t.business_day_id = bd.id
JOIN employees e ON e.full_name = 'PEDRO' AND e.tenant_id = 1
WHERE bd.business_date = '2026-05-03' AND t.daily_seq = 1 AND bd.tenant_id = 1
